import{_ as t,o as s,c as a,a2 as o}from"./chunks/framework.CZqXuAiL.js";const g=JSON.parse('{"title":"Configuration Reference","description":"Every Pterodactyl Revamp configuration surface — the revamp_settings keys with defaults and validation rules, config/revamp.php, the REVAMP_BULK_SYNC env var, and the Blueprint conf.yml / Components.yml manifests.","frontmatter":{"title":"Configuration Reference","description":"Every Pterodactyl Revamp configuration surface — the revamp_settings keys with defaults and validation rules, config/revamp.php, the REVAMP_BULK_SYNC env var, and the Blueprint conf.yml / Components.yml manifests."},"headers":[],"relativePath":"pterodactyl-revamp/configuration/reference.md","filePath":"pterodactyl-revamp/configuration/reference.md","lastUpdated":1785513726000}'),i={name:"pterodactyl-revamp/configuration/reference.md"};function n(r,e,d,l,h,c){return s(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="configuration-reference" tabindex="-1">Configuration Reference <a class="header-anchor" href="#configuration-reference" aria-label="Permalink to &quot;Configuration Reference&quot;">​</a></h1><p>Pterodactyl Revamp has <strong>four configuration surfaces</strong>, each serving a different purpose:</p><table tabindex="0"><thead><tr><th>Surface</th><th>Where it lives</th><th>Who changes it</th></tr></thead><tbody><tr><td><a href="#runtime-settings-revamp-settings">Runtime settings</a></td><td><code>revamp_settings</code> database table, edited at <code>/admin/revamp/settings</code></td><td>Panel admins, any time</td></tr><tr><td><a href="#config-revamp-php"><code>config/revamp.php</code></a></td><td>Panel root <code>config/</code> folder</td><td>Rarely — set at install time</td></tr><tr><td><a href="#revamp-bulk-sync"><code>REVAMP_BULK_SYNC</code></a></td><td><code>.env</code> / server environment</td><td>Debugging or worker-less setups</td></tr><tr><td><a href="#blueprint-manifest-conf-yml">Blueprint manifests</a></td><td><code>conf.yml</code> / <code>Components.yml</code> inside the extension</td><td>Extension packaging only — not runtime</td></tr></tbody></table><p>Most admins only ever touch the first one. The rest of this page documents every key, in order of how likely you are to need it.</p><hr><h2 id="runtime-settings-revamp-settings" tabindex="-1">Runtime Settings (<code>revamp_settings</code>) <a class="header-anchor" href="#runtime-settings-revamp-settings" aria-label="Permalink to &quot;Runtime Settings (`revamp_settings`)&quot;">​</a></h2><p>All runtime settings are stored as key-value rows in the <strong><code>revamp_settings</code></strong> table (primary key <code>key</code>, column <code>value</code>). Reads go through <code>RevampSettingsRepository</code>, which caches every key for <strong>5 minutes</strong> — writes through the admin UI flush the cache entry immediately, so changes made in the panel are live on the next request.</p><p>If a key has no row in the table, the typed default from the repository&#39;s <code>DEFAULTS</code> constant is used. This means you can delete a row to revert that key to its default.</p><div class="warning custom-block"><p class="custom-block-title">Editing the table directly</p><p>If you change <code>revamp_settings</code> rows with SQL instead of the admin UI, the 5-minute cache is <strong>not</strong> flushed. Either wait for the TTL or run <code>php artisan cache:clear</code> afterwards.</p></div><h3 id="settings-page-map" tabindex="-1">Settings page map <a class="header-anchor" href="#settings-page-map" aria-label="Permalink to &quot;Settings page map&quot;">​</a></h3><p>The settings form lives at <strong><code>/admin/revamp/settings</code></strong> (route <code>admin.revamp.settings</code>, root admins only) and posts to <code>admin.revamp.settings.update</code>. Every field is validated by <code>UpdateSettingsRequest</code> — the rules below are the hard limits; out-of-range values are rejected with a form error.</p><table tabindex="0"><thead><tr><th>UI section</th><th>UI field</th><th>Settings key</th><th>Default</th><th>Validation</th></tr></thead><tbody><tr><td>Auto-Naming</td><td>Naming Pattern</td><td><code>naming_pattern</code></td><td><code>{server_id} - {username}</code></td><td>required, string, max 191</td></tr><tr><td>Allocations</td><td>Allocations per Page</td><td><code>allocation_page_size</code></td><td><code>50</code></td><td>required, integer, 10–200</td></tr><tr><td>Metrics &amp; Upgrade Suggestions</td><td>Raw Sample Retention (days)</td><td><code>metrics_retention_days</code></td><td><code>90</code></td><td>required, integer, 7–3650</td></tr><tr><td>Metrics &amp; Upgrade Suggestions</td><td>CPU Threshold (%)</td><td><code>upgrade_cpu_threshold</code></td><td><code>85</code></td><td>required, integer, 1–100</td></tr><tr><td>Metrics &amp; Upgrade Suggestions</td><td>RAM Threshold (%)</td><td><code>upgrade_ram_threshold</code></td><td><code>85</code></td><td>required, integer, 1–100</td></tr><tr><td>Metrics &amp; Upgrade Suggestions</td><td>Disk Threshold (%)</td><td><code>upgrade_disk_threshold</code></td><td><code>90</code></td><td>required, integer, 1–100</td></tr><tr><td>Metrics &amp; Upgrade Suggestions</td><td>Evaluation Window (hours)</td><td><code>upgrade_window_hours</code></td><td><code>72</code></td><td>required, integer, 1–8760</td></tr><tr><td>Metrics &amp; Upgrade Suggestions</td><td>Suggestion Cooldown (hours)</td><td><code>upgrade_cooldown_hours</code></td><td><code>168</code></td><td>required, integer, 1–8760</td></tr><tr><td>Metrics &amp; Upgrade Suggestions</td><td>Suggestion Message</td><td><code>upgrade_message</code></td><td>see below</td><td>required, string, max 500</td></tr><tr><td>Health &amp; Instability Detection</td><td>Crash Loop Threshold (restarts)</td><td><code>health_crash_threshold</code></td><td><code>5</code></td><td>required, integer, 1–100</td></tr><tr><td>Health &amp; Instability Detection</td><td>Health Window (hours)</td><td><code>health_window_hours</code></td><td><code>24</code></td><td>required, integer, 1–168</td></tr><tr><td>Health &amp; Instability Detection</td><td>Health Data Retention (days)</td><td><code>health_retention_days</code></td><td><code>30</code></td><td>required, integer, 1–365</td></tr><tr><td>Health &amp; Instability Detection</td><td>Node Warn Pressure (%)</td><td><code>node_pressure_warn_pct</code></td><td><code>75</code></td><td>required, integer, 1–99</td></tr><tr><td>Health &amp; Instability Detection</td><td>Node Critical Pressure (%)</td><td><code>node_pressure_crit_pct</code></td><td><code>90</code></td><td>required, integer, 1–100</td></tr><tr><td>Bulk Operations</td><td>Enable bulk server move</td><td><code>bulk_move_enabled</code></td><td><code>false</code> (off)</td><td>required, boolean</td></tr></tbody></table><p>The default <code>upgrade_message</code> is:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Your server may benefit from a larger plan based on recent resource usage.</span></span></code></pre></div><p><strong>Every key above has a settings-page UI.</strong> The only runtime key <em>not</em> on this page is <a href="#tags-visible-to-users"><code>tags_visible_to_users</code></a>, which is toggled from the Tags page instead.</p><hr><h3 id="naming-pattern" tabindex="-1"><code>naming_pattern</code> <a class="header-anchor" href="#naming-pattern" aria-label="Permalink to &quot;`naming_pattern`&quot;">​</a></h3><ul><li><strong>Type:</strong> string · <strong>Default:</strong> <code>{server_id} - {username}</code> · <strong>UI:</strong> Settings page</li></ul><p>The auto-naming pattern applied when servers are created through Revamp&#39;s multi-server create flow (and anywhere else <code>NamingPatternEngine</code> is used). The pattern is resolved by <code>NamingPatternEngine::resolve()</code> at creation time.</p><p><strong>Supported tokens</strong> (anything else is left in the name literally):</p><table tabindex="0"><thead><tr><th>Token</th><th>Resolves to</th><th>Example output</th></tr></thead><tbody><tr><td><code>{server_id}</code></td><td>Sequential server id supplied by the caller</td><td><code>42</code></td></tr><tr><td><code>{username}</code></td><td>Owner&#39;s username (<code>admin</code> if unknown)</td><td><code>steve</code></td></tr><tr><td><code>{ram}</code></td><td>Memory limit — <strong>includes the <code>MB</code> suffix</strong></td><td><code>4096MB</code></td></tr><tr><td><code>{disk}</code></td><td>Disk limit — <strong>includes the <code>MB</code> suffix</strong></td><td><code>10240MB</code></td></tr><tr><td><code>{cpu}</code></td><td>CPU limit — <strong>includes the <code>%</code> suffix</strong></td><td><code>200%</code></td></tr><tr><td><code>{egg}</code></td><td>Egg name (<code>unknown</code> if unset)</td><td><code>Minecraft</code></td></tr><tr><td><code>{node}</code></td><td>Node name (<code>unknown</code> if unset)</td><td><code>node-01</code></td></tr><tr><td><code>{index}</code></td><td>1-based position within a batch create</td><td><code>3</code></td></tr></tbody></table><p><strong>When to change it:</strong> when you want multi-created servers to sort or read consistently in the server list — e.g. <code>{egg} #{index} - {username}</code>.</p><p><strong>Common mistakes:</strong></p><ul><li>Adding your own unit suffixes: <code>{ram}MB</code> renders as <code>4096MBMB</code>, and <code>{cpu}%</code> renders as <code>200%%</code>. The units are already baked into the token.</li><li>Expecting arbitrary characters to survive: after token replacement the engine strips everything outside <code>[\\w\\s\\-_.:()\\[\\]#@]</code> and truncates to 191 characters, so emoji and most punctuation silently disappear.</li></ul><hr><h3 id="allocation-page-size" tabindex="-1"><code>allocation_page_size</code> <a class="header-anchor" href="#allocation-page-size" aria-label="Permalink to &quot;`allocation_page_size`&quot;">​</a></h3><ul><li><strong>Type:</strong> integer · <strong>Default:</strong> <code>50</code> · <strong>Range:</strong> 10–200 · <strong>UI:</strong> Settings page</li></ul><p>How many allocations the allocation port picker loads per page when you browse a node&#39;s ports (<code>AllocationPickerService</code>).</p><p><strong>When to change it:</strong> raise it on nodes with many free ports so admins scroll less; lower it if the picker feels slow on very large nodes.</p><p><strong>Common mistake:</strong> setting it below 10 or above 200 — the form validation rejects anything outside that range.</p><hr><h3 id="metrics-retention-days" tabindex="-1"><code>metrics_retention_days</code> <a class="header-anchor" href="#metrics-retention-days" aria-label="Permalink to &quot;`metrics_retention_days`&quot;">​</a></h3><ul><li><strong>Type:</strong> integer · <strong>Default:</strong> <code>90</code> · <strong>Range:</strong> 7–3650 · <strong>UI:</strong> Settings page</li></ul><p>How long raw metric samples are kept in <code>revamp_metric_samples</code>. Samples are collected every 5 minutes by the scheduled <code>revamp:sample-metrics</code> command (rolled up hourly by <code>revamp:rollup-metrics</code>), and <code>MetricSamplingService</code> prunes rows older than this window.</p><p><strong>When to change it:</strong> lower it if the metrics table grows too large on busy panels; raise it if you need longer trend history in analytics.</p><p><strong>Common mistake:</strong> cranking it to the maximum on a panel with hundreds of servers — raw samples accrue every 5 minutes per server, so retention directly multiplies table size. The hourly rollups are the long-term store; raw samples are the short-term one.</p><hr><h3 id="upgrade-cpu-threshold-upgrade-ram-threshold-upgrade-disk-threshold" tabindex="-1"><code>upgrade_cpu_threshold</code> / <code>upgrade_ram_threshold</code> / <code>upgrade_disk_threshold</code> <a class="header-anchor" href="#upgrade-cpu-threshold-upgrade-ram-threshold-upgrade-disk-threshold" aria-label="Permalink to &quot;`upgrade_cpu_threshold` / `upgrade_ram_threshold` / `upgrade_disk_threshold`&quot;">​</a></h3><ul><li><strong>Type:</strong> integer (percent) · <strong>Defaults:</strong> <code>85</code> / <code>85</code> / <code>90</code> · <strong>Range:</strong> 1–100 · <strong>UI:</strong> Settings page</li></ul><p>Utilization percentages the <code>UpgradeRuleEngine</code> compares against a server&#39;s recent usage. When usage stays at or above a threshold across the evaluation window, an upgrade suggestion is generated for that server.</p><p><strong>When to change them:</strong> lower them to surface suggestions earlier (more aggressive upsell), raise them to only flag genuinely saturated servers.</p><p><strong>Common mistake:</strong> treating these as instantaneous triggers — a single spike does nothing; usage must stay high across <code>upgrade_window_hours</code>.</p><hr><h3 id="upgrade-window-hours" tabindex="-1"><code>upgrade_window_hours</code> <a class="header-anchor" href="#upgrade-window-hours" aria-label="Permalink to &quot;`upgrade_window_hours`&quot;">​</a></h3><ul><li><strong>Type:</strong> integer (hours) · <strong>Default:</strong> <code>72</code> · <strong>Range:</strong> 1–8760 · <strong>UI:</strong> Settings page</li></ul><p>The lookback window the <code>UpgradeRuleEngine</code> evaluates usage over before suggesting an upgrade.</p><p><strong>When to change it:</strong> shorten it for faster reaction to sustained load; lengthen it to smooth out weekend spikes and only catch chronic pressure.</p><p><strong>Common mistake:</strong> setting it shorter than your metric sampling cadence can cover — the scheduler samples every 5 minutes, so a 1-hour window gives the engine only ~12 samples to judge from.</p><hr><h3 id="upgrade-cooldown-hours" tabindex="-1"><code>upgrade_cooldown_hours</code> <a class="header-anchor" href="#upgrade-cooldown-hours" aria-label="Permalink to &quot;`upgrade_cooldown_hours`&quot;">​</a></h3><ul><li><strong>Type:</strong> integer (hours) · <strong>Default:</strong> <code>168</code> (7 days) · <strong>Range:</strong> 1–8760 · <strong>UI:</strong> Settings page</li></ul><p>Minimum time before the same server can receive another upgrade suggestion.</p><p><strong>When to change it:</strong> lower it if you want dismissed or ignored suggestions to reappear sooner; raise it to nag less.</p><p><strong>Common mistake:</strong> setting it to <code>0</code>-like values to &quot;re-test&quot; suggestions — the form enforces a minimum of 1 hour.</p><hr><h3 id="upgrade-message" tabindex="-1"><code>upgrade_message</code> <a class="header-anchor" href="#upgrade-message" aria-label="Permalink to &quot;`upgrade_message`&quot;">​</a></h3><ul><li><strong>Type:</strong> string · <strong>Default:</strong> <code>Your server may benefit from a larger plan based on recent resource usage.</code> · <strong>Limit:</strong> 500 chars · <strong>UI:</strong> Settings page</li></ul><p>The message text attached to generated upgrade suggestions.</p><p><strong>When to change it:</strong> to match your panel&#39;s tone or to point users at your upgrade/ordering flow.</p><hr><h3 id="health-crash-threshold" tabindex="-1"><code>health_crash_threshold</code> <a class="header-anchor" href="#health-crash-threshold" aria-label="Permalink to &quot;`health_crash_threshold`&quot;">​</a></h3><ul><li><strong>Type:</strong> integer (restarts) · <strong>Default:</strong> <code>5</code> · <strong>Range:</strong> 1–100 · <strong>UI:</strong> Settings page</li></ul><p>How many restarts inside the health window mark a server as a crash-looping / unstable server. Used by both <code>ServerHealthService</code> and <code>NodeHealthService</code> when the scheduled <code>revamp:compute-health</code> command (every 10 minutes) builds health snapshots.</p><p><strong>When to change it:</strong> raise it for eggs that legitimately restart often (e.g. auto-restart-on-crash setups) so they stop flagging; lower it to catch instability earlier.</p><hr><h3 id="health-window-hours" tabindex="-1"><code>health_window_hours</code> <a class="header-anchor" href="#health-window-hours" aria-label="Permalink to &quot;`health_window_hours`&quot;">​</a></h3><ul><li><strong>Type:</strong> integer (hours) · <strong>Default:</strong> <code>24</code> · <strong>Range:</strong> 1–168 · <strong>UI:</strong> Settings page</li></ul><p>The rolling window in which restarts are counted against <code>health_crash_threshold</code>.</p><p><strong>When to change it:</strong> shorten it so only <em>recent</em> crash loops flag; lengthen it to catch slow-burn instability.</p><p><strong>Common mistake:</strong> pairing a long window with a low threshold — that combination flags almost every server that restarts occasionally.</p><hr><h3 id="health-retention-days" tabindex="-1"><code>health_retention_days</code> <a class="header-anchor" href="#health-retention-days" aria-label="Permalink to &quot;`health_retention_days`&quot;">​</a></h3><ul><li><strong>Type:</strong> integer (days) · <strong>Default:</strong> <code>30</code> · <strong>Range:</strong> 1–365 · <strong>UI:</strong> Settings page</li></ul><p>How long computed health snapshots are retained. <code>ComputeHealthJob</code> prunes snapshots older than this on each run.</p><p><strong>When to change it:</strong> raise it if you use the health pages for longer-term node trend review; lower it to keep the <code>revamp_server_health_snapshots</code> and <code>revamp_node_health_snapshots</code> tables small.</p><hr><h3 id="node-pressure-warn-pct-node-pressure-crit-pct" tabindex="-1"><code>node_pressure_warn_pct</code> / <code>node_pressure_crit_pct</code> <a class="header-anchor" href="#node-pressure-warn-pct-node-pressure-crit-pct" aria-label="Permalink to &quot;`node_pressure_warn_pct` / `node_pressure_crit_pct`&quot;">​</a></h3><ul><li><strong>Type:</strong> integer (percent) · <strong>Defaults:</strong> <code>75</code> / <code>90</code> · <strong>Ranges:</strong> 1–99 / 1–100 · <strong>UI:</strong> Settings page</li></ul><p>The pressure percentages at which <code>NodeHealthService</code> grades a node as <strong>warning</strong> or <strong>critical</strong> on the health pages.</p><p><strong>When to change them:</strong> align them with your real overcommit policy — e.g. if you deliberately overcommit RAM, the default warn level may flag healthy nodes.</p><p><strong>Common mistake:</strong> setting warn <strong>above</strong> crit. The form validates each field independently (warn 1–99, crit 1–100) but does <strong>not</strong> check their ordering, so <code>warn=95, crit=90</code> saves fine and produces inverted grading. Keep warn below crit.</p><hr><h3 id="bulk-move-enabled" tabindex="-1"><code>bulk_move_enabled</code> <a class="header-anchor" href="#bulk-move-enabled" aria-label="Permalink to &quot;`bulk_move_enabled`&quot;">​</a></h3><ul><li><strong>Type:</strong> boolean · <strong>Default:</strong> <code>false</code> (off) · <strong>UI:</strong> Settings page (danger-styled box)</li></ul><p>Master switch for the <strong>bulk move</strong> bulk-operation type. <code>BulkMoveService</code> refuses to run while this is off.</p><div class="danger custom-block"><p class="custom-block-title">Bulk move does not transfer server data</p><p>Enabling <code>bulk_move_enabled</code> only allows Revamp to <strong>re-point the panel&#39;s database records</strong> (node and allocation) for the selected servers. It does <strong>not</strong> transfer any server data through Wings. A &quot;moved&quot; server keeps its files on the old node and will be broken until a real data transfer happens separately. Only enable this if you have an external migration process that handles the bytes.</p></div><p><strong>When to change it:</strong> only while you are actively running a record-only re-point migration, then turn it back off.</p><p><strong>Common mistake:</strong> enabling it and expecting a normal Pterodactyl server transfer — the stock transfer feature (which does move data via Wings) is a different mechanism entirely.</p><hr><h3 id="tags-visible-to-users" tabindex="-1"><code>tags_visible_to_users</code> <a class="header-anchor" href="#tags-visible-to-users" aria-label="Permalink to &quot;`tags_visible_to_users`&quot;">​</a></h3><ul><li><strong>Type:</strong> boolean · <strong>Default:</strong> <code>false</code> (off) · <strong>UI:</strong> <strong>Tags page</strong> (<code>/admin/revamp/tags</code>), not the settings page</li></ul><p>Controls whether server owners can see the tags assigned to their server. When off, the client API endpoint (<code>GET /api/client/servers/{server}/tags</code>, registered by the Blueprint client router) responds with <code>{&quot;visible&quot;: false, &quot;tags&quot;: []}</code> regardless of what tags exist. When on, it returns the server&#39;s tag list.</p><p>This key is set through its own route (<code>POST /admin/revamp/tags/settings</code>, validated as <code>nullable|boolean</code>) rather than the main settings form — it is the only runtime key without a field on the settings page.</p><p><strong>When to change it:</strong> turn it on if you use tags as user-facing labels (e.g. plan tiers); leave it off when tags are internal ops metadata.</p><hr><h2 id="config-revamp-php" tabindex="-1"><code>config/revamp.php</code> <a class="header-anchor" href="#config-revamp-php" aria-label="Permalink to &quot;`config/revamp.php`&quot;">​</a></h2><p>A standard Laravel config file merged by <code>RevampServiceProvider</code> (<code>mergeConfigFrom</code>, namespace <code>revamp</code>). It ships with a single key:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;admin_home_route&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;admin.revamp.index&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span></span></code></pre></div><h3 id="revamp-admin-home-route" tabindex="-1"><code>revamp.admin_home_route</code> <a class="header-anchor" href="#revamp-admin-home-route" aria-label="Permalink to &quot;`revamp.admin_home_route`&quot;">​</a></h3><ul><li><strong>Type:</strong> string (route name) · <strong>Default:</strong> <code>admin.revamp.index</code></li></ul><p>Tells <code>RevampNav::homeRouteName()</code> which named route &quot;Revamp home&quot; links should point at. The resolver checks the configured route first, then falls back in order:</p><ol><li>The configured route, if it exists and is non-empty.</li><li><code>admin.revamp.index</code> (the Revamp dashboard at <code>/admin/revamp</code>).</li><li><code>admin.extensions.pterodactylrevamp.index</code> (the Blueprint Extensions hub page).</li></ol><p>The Blueprint installer rewrites this file during install so the admin home points at the Extensions hub on Blueprint-based panels.</p><p><strong>When to change it:</strong> practically never — the fallback chain already covers both install paths. Only touch it if you have customized admin routing.</p><p><strong>Common mistake:</strong> pointing it at a route that does not exist and expecting an error — there is none; the resolver silently falls back down the chain.</p><p>After editing, clear the config cache:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config:clear</span></span></code></pre></div><hr><h2 id="revamp-bulk-sync" tabindex="-1"><code>REVAMP_BULK_SYNC</code> <a class="header-anchor" href="#revamp-bulk-sync" aria-label="Permalink to &quot;`REVAMP_BULK_SYNC`&quot;">​</a></h2><ul><li><strong>Type:</strong> boolean env var · <strong>Default:</strong> <code>false</code> (absent = async)</li></ul><p>Read directly by <code>BulkOperationService</code> when a bulk operation is dispatched:</p><ul><li><strong>Unset / <code>false</code></strong> — the bulk job is dispatched onto the dedicated <strong><code>revamp</code> queue</strong> and processed by your queue worker (<code>php artisan queue:work --queue=revamp,default</code>). This is the normal production mode.</li><li><strong><code>true</code></strong> — the job runs <strong>synchronously inside the HTTP request</strong> (<code>dispatch_sync</code>). No queue worker is needed.</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># .env</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">REVAMP_BULK_SYNC</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">true</span></span></code></pre></div><p><strong>When to change it:</strong> local development, debugging a failing bulk job, or a tiny panel where you deliberately run no queue worker.</p><p><strong>Common mistakes:</strong></p><ul><li>Leaving it on in production — a bulk suspend/delete across dozens of servers blocks the web request until every item finishes, and the request will hit your web server&#39;s timeout first.</li><li>Setting it in <code>.env</code> while running <code>php artisan config:cache</code>. The value is read via <code>env()</code> at runtime rather than through a config file, and Laravel does not load <code>.env</code> when the config is cached — so the setting is silently ignored. Either set it as a real environment variable or avoid config caching.</li></ul><hr><h2 id="scheduler-queue-interplay" tabindex="-1">Scheduler &amp; queue interplay <a class="header-anchor" href="#scheduler-queue-interplay" aria-label="Permalink to &quot;Scheduler &amp; queue interplay&quot;">​</a></h2><p>Retention and threshold settings only take effect because the scheduler runs the commands that consume them. <code>RevampServiceProvider</code> registers these at boot (no <code>Kernel.php</code> edit needed), driven by the standard Pterodactyl cron entry:</p><table tabindex="0"><thead><tr><th>Command</th><th>Frequency</th><th>Overlap lock</th><th>Consumes</th></tr></thead><tbody><tr><td><code>revamp:sample-metrics</code></td><td>every 5 minutes</td><td>10 min</td><td><code>metrics_retention_days</code></td></tr><tr><td><code>revamp:rollup-metrics</code></td><td>hourly</td><td>30 min</td><td>—</td></tr><tr><td><code>revamp:compute-health</code></td><td>every 10 minutes</td><td>15 min</td><td><code>health_*</code>, <code>node_pressure_*</code></td></tr><tr><td><code>revamp:evaluate-rules</code></td><td>daily at 03:00</td><td>60 min</td><td><code>upgrade_*</code></td></tr></tbody></table><p>Commands dispatch their heavy work onto the <code>revamp</code> queue, so both the cron entry <strong>and</strong> a worker listening on <code>revamp</code> must be running — see <a href="/pingless-studios-docs/pterodactyl-revamp/getting-started/installation#post-install-steps">Post-Install Steps</a>.</p><hr><h2 id="blueprint-manifest-conf-yml" tabindex="-1">Blueprint manifest: <code>conf.yml</code> <a class="header-anchor" href="#blueprint-manifest-conf-yml" aria-label="Permalink to &quot;Blueprint manifest: `conf.yml`&quot;">​</a></h2><p><code>blueprint/pterodactylrevamp/conf.yml</code> is the <strong>Blueprint extension manifest</strong>. Blueprint reads it at install time only — editing it on an installed panel changes nothing. It is documented here for anyone rebuilding or forking the extension.</p><h3 id="info" tabindex="-1"><code>info</code> <a class="header-anchor" href="#info" aria-label="Permalink to &quot;`info`&quot;">​</a></h3><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">info</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Pterodactyl Revamp&quot;</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  identifier</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pterodactylrevamp&quot;</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Enterprise operations suite — bulk ops, tagging, templates, allocation UX, and audit logging.&quot;</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  flags</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1.2.0&quot;</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  target</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;beta-2026-06&quot;</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  author</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;PingLess&quot;</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  website</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Key</th><th>Value</th><th>Notes</th></tr></thead><tbody><tr><td><code>info.identifier</code></td><td><code>pterodactylrevamp</code></td><td>Used for <code>blueprint -i/-remove</code> and the install-marker tags in patched files. Must stay unique.</td></tr><tr><td><code>info.version</code></td><td><code>1.2.0</code></td><td>Bump on every release; Blueprint shows it in the Extensions hub.</td></tr><tr><td><code>info.target</code></td><td><code>beta-2026-06</code></td><td>Blueprint version the extension targets. Installing on a different Blueprint target may warn or fail.</td></tr><tr><td><code>info.flags</code></td><td><em>(empty)</em></td><td>No install flags are used.</td></tr><tr><td><code>info.website</code></td><td><em>(empty)</em></td><td>Optional; not set for this extension.</td></tr></tbody></table><h3 id="admin" tabindex="-1"><code>admin</code> <a class="header-anchor" href="#admin" aria-label="Permalink to &quot;`admin`&quot;">​</a></h3><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">admin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  view</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;view.blade.php&quot;</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  controller</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;controller.php&quot;</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  css</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  wrapper</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span></code></pre></div><p>Wires the extension&#39;s <strong>Blueprint Extensions hub page</strong>: <code>admin.view</code> and <code>admin.controller</code> are the hub view/controller pair. <code>admin.css</code> and <code>admin.wrapper</code> are empty — the hub page uses the panel&#39;s stock styling. This hub page is separate from the main Revamp admin UI at <code>/admin/revamp</code>, which is served by the PanelFiles merge.</p><h3 id="dashboard" tabindex="-1"><code>dashboard</code> <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;`dashboard`&quot;">​</a></h3><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">dashboard</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  css</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  wrapper</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  components</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;components&quot;</span></span></code></pre></div><p><code>dashboard.components</code> points at the <code>components/</code> folder containing <code>Components.yml</code> (see below) — Blueprint&#39;s mechanism for injecting React components into the client dashboard. <code>css</code> and <code>wrapper</code> are unused.</p><h3 id="data" tabindex="-1"><code>data</code> <a class="header-anchor" href="#data" aria-label="Permalink to &quot;`data`&quot;">​</a></h3><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">data</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  directory</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data&quot;</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  public</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  console</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span></code></pre></div><ul><li><code>data.directory: &quot;data&quot;</code> — the extension&#39;s <code>data/</code> folder, which contains the install/remove scripts (<code>install.sh</code>, <code>remove.sh</code>) Blueprint runs automatically.</li><li><code>data.public</code> — empty; no public assets are managed through this key. The admin UI islands (<code>public/ext/revamp/*.js</code> / <code>.css</code>) ship inside <code>PanelFiles/public/</code> and land on the panel through the normal file merge.</li><li><code>data.console</code> — empty; the addon needs no Blueprint console commands. Artisan commands load from <code>app/Console/Commands/**</code> automatically on Panel 1.12+.</li></ul><h3 id="requests" tabindex="-1"><code>requests</code> <a class="header-anchor" href="#requests" aria-label="Permalink to &quot;`requests`&quot;">​</a></h3><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">requests</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  views</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  app</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  routers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    application</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    client</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;routes/blueprint/client/revamp.php&quot;</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    web</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;routes/web.php&quot;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Key</th><th>Value</th><th>What it does</th></tr></thead><tbody><tr><td><code>requests.routers.client</code></td><td><code>routes/blueprint/client/revamp.php</code></td><td>Registers the client API route <code>GET /api/client/servers/{server}/tags</code> (behind <code>ServerSubject</code> + <code>AuthenticateServerAccess</code>) — the endpoint gated by <code>tags_visible_to_users</code>.</td></tr><tr><td><code>requests.routers.web</code></td><td><code>routes/web.php</code></td><td>Present but intentionally empty — the file contains only a comment. All real web routes are registered by <code>RevampServiceProvider</code> from <code>routes/admin-revamp.php</code> under the <code>/admin/revamp</code> prefix (<code>admin.revamp.*</code> names).</td></tr><tr><td><code>requests.routers.application</code></td><td><em>(empty)</em></td><td>Application API routes (<code>/api/application/revamp/*</code>) are likewise registered by the service provider from <code>routes/api-revamp.php</code>, not by Blueprint.</td></tr><tr><td><code>requests.views</code> / <code>requests.app</code></td><td><em>(empty)</em></td><td>Unused — views and app files land via the <code>PanelFiles/</code> merge.</td></tr></tbody></table><h3 id="database" tabindex="-1"><code>database</code> <a class="header-anchor" href="#database" aria-label="Permalink to &quot;`database`&quot;">​</a></h3><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">database</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  migrations</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span></code></pre></div><p>Empty on purpose: migrations are loaded by <code>RevampServiceProvider</code> via <code>loadMigrationsFrom()</code> and run with the normal <code>php artisan migrate --force</code>, not through Blueprint&#39;s migration key.</p><div class="warning custom-block"><p class="custom-block-title">Common manifest mistakes</p><ul><li><strong>Editing <code>conf.yml</code> on a live panel</strong> — Blueprint only reads it during install/remove. Rebuild the <code>.blueprint</code> archive and reinstall for manifest changes to apply.</li><li><strong>Filling in empty keys</strong> (<code>data.console</code>, <code>database.migrations</code>, <code>requests.routers.application</code>) assuming they are needed — they are empty because the service provider handles those concerns; duplicating them causes double registration.</li></ul></div><hr><h2 id="blueprint-component-map-components-yml" tabindex="-1">Blueprint component map: <code>Components.yml</code> <a class="header-anchor" href="#blueprint-component-map-components-yml" aria-label="Permalink to &quot;Blueprint component map: `Components.yml`&quot;">​</a></h2><p><code>blueprint/pterodactylrevamp/components/Components.yml</code> lists every React injection point Blueprint supports on the client dashboard. The extension uses exactly <strong>one</strong> of them:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  Settings</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    BeforeContent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;revampServerDebugTags&quot;</span></span></code></pre></div><p><code>Server → Settings → BeforeContent: revampServerDebugTags</code> injects the <code>revampServerDebugTags</code> component above the stock content of the client <strong>Server → Settings</strong> page — the client-side surface for server tags, which reads from the client API endpoint gated by <code>tags_visible_to_users</code>.</p><p>Every other injection point in the file (navigation, server rows, terminal, files, backups, network, startup, and the rest) is set to <code>&quot;&quot;</code> — declared but unused.</p><p><strong>Common mistakes:</strong></p><ul><li>Assuming the empty entries do something — they are placeholders only.</li><li>Editing <code>Components.yml</code> on an installed panel — like <code>conf.yml</code>, it is consumed at install time. Component changes require rebuilding the <code>.blueprint</code> file, removing, and reinstalling the extension.</li></ul><hr><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="/pingless-studios-docs/pterodactyl-revamp/">Pterodactyl Revamp overview</a> — feature tour</li><li><a href="/pingless-studios-docs/pterodactyl-revamp/getting-started/installation">Installation</a> — install paths, queue worker, and cron setup</li></ul>',154)])])}const u=t(i,[["render",n]]);export{g as __pageData,u as default};
